declare module "@hermes/plugin-sdk/~app/desktop/src/lib/budgeted-loop" {
  /**
   * Budgeted renderer loop — the one way to run a decorative rAF animation.
   *
   * Desktop has repeatedly shipped the same bug class: an animation loop that
   * never sleeps (bots face clock #88543, pixel egg #88406, diffusion
   * placeholder #88564, status pulse / spinner in the #77651 wave). Each fix
   * re-implemented the same four behaviors by hand. This helper owns them:
   *
   *  - **fps budget** — paints are skipped until `1000 / fps` elapsed; the loop
   *    still rides rAF so Chromium can align and pause it natively.
   *  - **observability pause** — wired to `createRendererLoopPauseController`:
   *    the loop cancels while the window is hidden or minimized and resumes
   *    when visible, even if another window has focus.
   *  - **idle dormancy** — when `idleWhen()` returns true after a draw, the loop
   *    parks (zero pending frames, zero timers) until `wake()` is called. This
   *    is the piece every hand-rolled loop forgot: "nothing visible to animate"
   *    must cost nothing.
   *  - **teardown** — `dispose()` cancels the frame, disposes the pause
   *    controller, and makes every later `wake()` a no-op. Callers MUST call it
   *    from their effect cleanup / plugin disposer.
   *
   * Usage:
   *
   * ```ts
   * const loop = createBudgetedLoop(now => paint(now), {
   *   fps: 15,
   *   idleWhen: () => visibleThings.size === 0
   * })
   * // something became animatable again:
   * loop.wake()
   * // effect cleanup / plugin disable:
   * loop.dispose()
   * ```
   */
  export interface BudgetedLoopOptions {
      /** Paint budget in frames per second. Default 15 — visually smooth for
       *  decorative/avatar-scale animation at a quarter of display cadence. */
      fps?: number;
      /** Return true when there is nothing worth animating (no visible targets,
       *  animation finished). Checked after every draw; when true the loop parks
       *  until `wake()`. Omit for loops that should run whenever observable. */
      idleWhen?: () => boolean;
      /** Forwarded to the pause controller. Default false (animate while visible). */
      pauseWhenUnfocused?: boolean;
  }
  export interface BudgetedLoop {
      /** Cancel everything and detach listeners. Idempotent; wake() after this is
       *  a no-op. Call from effect cleanup or the plugin disposer. */
      dispose: () => void;
      /** True while parked by `idleWhen` (diagnostics/tests). */
      isDormant: () => boolean;
      /** Resume a loop parked by `idleWhen` (e.g. a target mounted or scrolled
       *  into view). Safe to call redundantly; no-op while running or disposed. */
      wake: () => void;
  }
  export function createBudgetedLoop(draw: (now: number) => void, { fps, idleWhen, pauseWhenUnfocused }?: BudgetedLoopOptions): BudgetedLoop;
}

declare module "@hermes/plugin-sdk/~app/desktop/src/lib/chat-empty" {
  import type { ReactNode } from 'react';
  /**
   * CHAT EMPTY STATE — the blank transcript as a contribution area.
   *
   * Core owns exactly one empty state: the intro splash, which belongs to a
   * fresh draft with no session selected. A session that exists but has nothing
   * in it yet falls outside that — and whoever opened it is the only one who
   * knows what should stand in the gap. A bot's chat wants the bot's face and
   * name; core has neither, and should not learn them.
   *
   * So the slot is contributed. A plugin claims the sessions it owns by
   * returning an element for them and `null` for everything else, which is also
   * how it stands down while the transcript is still hydrating.
   *
   * Ownership is per session, so EVERY registration is mounted and each answers
   * for itself. Declining is free; two plugins claiming one session render both,
   * which is the visible cost of never letting registration order silently
   * suppress the plugin that actually owns the chat.
   */
  export const CHAT_EMPTY_AREA = "chat.empty";
  /** Props handed to a chat-empty contribution's `render`. */
  export interface ChatEmptyProps {
      /** The live session whose transcript is empty. */
      sessionId: string;
      /** Its stored id, when the surface knows it (absent on older desktops). */
      storedSessionId?: string;
      /** The Bot Mode owner the session was opened for (opaque key the tab
       *  carries) — a bot's side chat, not only its canonical one. */
      workspaceOwnerKey?: string;
  }
  /** Payload of a `chat.empty` contribution's `data`. */
  export interface ChatEmptyContribution {
      /** Renders the empty state, or returns `null` to decline the session and
       *  leave the transcript blank. Mounted as a component inside the
       *  contribution error boundary, so it can subscribe to its own stores and
       *  appear once they load — the roster a bot chat needs arrives after the
       *  transcript does. A throw degrades to an inline error, not a dead chat. */
      render: (props: ChatEmptyProps) => ReactNode;
  }
}

